effect:
event.row.holds.map(
  h,
  {
    "collection": "payslip",
    "operation": "update",
    "data": {
      "target": slips.filter(s, s.employment_id == h.employment_id).map(
        s,
        s.id
      ),
      "set": {"status": "ON_HOLD"}
    }
  }
).filter(
  w,
  size(w.data.target) > 0
)

catalogues.filter(
  c,
  !movements.exists(
    m,
    m.reference
    =="window:" + event.row.id + ":" + c.code + ":" + event.day
  )
).map(
  c,
  {
    "collection": "leave_catalog_entry",
    "operation": "create",
    "data": {
      "catalog_id": c.id,
      "employment_id": event.row.id,
      "occurred_on": event.day,
      "activity": "ENCASHMENT",
      "reference": "window:" + event.row.id + ":" + c.code + ":"
      +event.day,
      "days": max(
        0.0,
        sum(
          event.leave_balances.filter(
            b,
            b.code == c.code && b.window_to == event.day
          ).map(
            b,
            b.remaining
          )
        )
      )
    }
  }
).filter(
  w,
  w.data.days > 0
)

